1	//! Deterministic HHTL topology key — map each bus to its `(HEEL, HIP, TWIG)`
2	//! cascade-tier address by recursive Cheeger bisection of the Laplacian.
3	//!
4	//! This makes "topology IS the key" concrete (the HHTL-OGAR correction): the key
5	//! is a **pure, deterministic function of the graph spectrum** — Cheeger/Fiedler
6	//! is deterministic given the Laplacian, so the same grid always yields the same
7	//! HHTL grid. Value members (the study factors, helix residues) then hang off this
8	//! key, orthogonal to it by the key/value split.
9	//!
10	//! Tiers here are produced by **binary** Cheeger splits (one bit per level → the
11	//! HHTL depth-3 tree = 8 leaf basins), the same compartmentalization the
12	//! `resilience` example uses. The OGAR production form widens each tier to a 16-ary
13	//! / 256-centroid tile (`FAN_OUT=16`); this is the spectral-bisection instance of
14	//! the same address, not that full encoding (kept honest).
15	
16	use crate::graph::{Edge, Grid};
17	use crate::{cheeger_sweep, symmetric_eigen};
18	use std::collections::HashMap;
19	
20	/// A node's HHTL cascade address: the path through the recursive bisection tree.
21	/// `heel` = top tier, `hip` = mid, `twig` = leaf. (u16 to match the OGAR key
22	/// layout; the binary-Cheeger instance only fills the low bits per tier.)
23	#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
24	pub struct HhtlKey {
25	    pub heel: u16,
26	    pub hip: u16,
27	    pub twig: u16,
28	}
29	
30	/// Induced sub-grid on `members` (reindexed 0..k), edges with both endpoints kept.
31	fn induced(grid: &Grid, members: &[usize]) -> Grid {
32	    let mut remap = HashMap::new();
33	    for (i, &m) in members.iter().enumerate() {
34	        remap.insert(m, i);
35	    }
36	    let edges = grid
37	        .edges
38	        .iter()
39	        .filter_map(|e| match (remap.get(&e.from), remap.get(&e.to)) {
40	            (Some(&a), Some(&b)) => Some(Edge::new(a, b, e.susceptance, e.limit)),
41	            _ => None,
42	        })
43	        .collect();
44	    Grid::new(members.len(), edges)
45	}
46	
47	/// One deterministic binary Cheeger split of `members` into (bit-0 side, bit-1
48	/// side). A basin too small / too sparse to split returns everything on bit 0.
49	fn split(grid: &Grid, members: &[usize]) -> (Vec<usize>, Vec<usize>) {
50	    if members.len() < 4 {
51	        return (members.to_vec(), Vec::new());
52	    }
53	    let sub = induced(grid, members);
54	    if sub.edges.is_empty() {
55	        return (members.to_vec(), Vec::new());
56	    }
57	    let part = cheeger_sweep(&sub, &vec![true; sub.edges.len()]).partition;
58	    let (mut a, mut b) = (Vec::new(), Vec::new());
59	    for (i, &m) in members.iter().enumerate() {
60	        if part[i] {
61	            a.push(m);
62	        } else {
63	            b.push(m);
64	        }
65	    }
66	    if a.is_empty() || b.is_empty() {
67	        (members.to_vec(), Vec::new())
68	    } else {
69	        (a, b)
70	    }
71	}
