73	/// Assign every node its `(HEEL, HIP, TWIG)` key by three nested binary Cheeger
74	/// splits. Deterministic: a pure function of the grid topology.
75	pub fn hhtl_keys(grid: &Grid) -> Vec<HhtlKey> {
76	    let mut keys = vec![
77	        HhtlKey {
78	            heel: 0,
79	            hip: 0,
80	            twig: 0
81	        };
82	        grid.n
83	    ];
84	    let all: Vec<usize> = (0..grid.n).collect();
85	    let (h0, h1) = split(grid, &all);
86	    for (heel, side) in [h0, h1].into_iter().enumerate() {
87	        for &n in &side {
88	            keys[n].heel = heel as u16;
89	        }
90	        let (p0, p1) = split(grid, &side);
91	        for (hip, mid) in [p0, p1].into_iter().enumerate() {
92	            for &n in &mid {
93	                keys[n].hip = hip as u16;
94	            }
95	            let (t0, t1) = split(grid, &mid);
96	            for (twig, leaf) in [t0, t1].into_iter().enumerate() {
97	                for &n in &leaf {
98	                    keys[n].twig = twig as u16;
99	                }
100	            }
101	        }
102	    }
103	    keys
104	}
