106	/// Per-leaf-basin algebraic connectivity `λ₂` keyed by HHTL address — the topology
107	/// "value" the key indexes (read once from the spectrum, deterministic).
108	pub fn basin_lambda2(grid: &Grid, keys: &[HhtlKey]) -> HashMap<HhtlKey, f64> {
109	    assert_eq!(
110	        keys.len(),
111	        grid.n,
112	        "basin_lambda2 requires exactly one HHTL key per grid node (got {} keys for {} nodes)",
113	        keys.len(),
114	        grid.n
115	    );
116	    let mut groups: HashMap<HhtlKey, Vec<usize>> = HashMap::new();
117	    for (n, k) in keys.iter().enumerate() {
118	        groups.entry(*k).or_default().push(n);
119	    }
120	    let mut out = HashMap::new();
121	    for (k, members) in groups {
122	        let sub = induced(grid, &members);
123	        let l2 = if sub.edges.is_empty() {
124	            0.0
125	        } else {
126	            symmetric_eigen(&sub.laplacian_of(&vec![true; sub.edges.len()]), sub.n)
127	                .values
128	                .get(1)
129	                .copied()
130	                .unwrap_or(0.0)
131	        };
132	        out.insert(k, l2);
133	    }
134	    out
135	}
