//! CLAM Tree: divisive hierarchical clustering with LFD estimation.
//!
//! Implements Algorithm 1 (Partition) from CAKES (arXiv:2309.05491):
//!
//! ```text
//! 1. seeds ← random sample of ⌈√|C|⌉ points from C
//! 2. c     ← geometric median of seeds
//! 3. l     ← argmax f(c, x)  ∀x ∈ C          (left pole)
//! 4. r     ← argmax f(l, x)  ∀x ∈ C          (right pole)
//! 5. L     ← { x | f(l,x) ≤ f(r,x) }
//! 6. R     ← { x | f(r,x) < f(l,x) }
//! 7. recurse on L, R
//! ```
//!
//! After construction, the dataset is depth-first reordered so each cluster
//! is a contiguous slice `[offset..offset+cardinality]` — O(n) memory
//! instead of O(n log n) from storing index lists (CAKES §2.1.2).
//!
//! ## LFD (Local Fractal Dimension)
//!
//! Per-cluster LFD is computed during construction using Equation 2 from CAKES:
//!
//! ```text
//! LFD(q, r) = log₂( |B(q, r)| / |B(q, r/2)| )
//! ```

use super::bitwise;

// ─── SplitMix64 RNG (local) ─────────────────────────────────────

struct SplitMix64(u64);

impl SplitMix64 {
    fn new(seed: u64) -> Self {
        Self(seed)
    }
    fn next_u64(&mut self) -> u64 {
        self.0 = self.0.wrapping_add(0x9E3779B97F4A7C15);
        let mut z = self.0;
        z = (z ^ (z >> 30)).wrapping_mul(0xBF58476D1CE4E5B9);

1	//! Morton-cascade inverse-pyramid Fisher-z reading over the V3 L4 palette tenant
2	//! — the CLEAN V3 thinking compute that REPLACES running the cluttered V1
3	//! `CausalEdge64` (3×8 bare indices) over the V3 substrate.
4	//!
5	//! Operator ruling: *"using cluttered V1 causaledge64 over v3 substrate is
6	//! extremely poor design … keep the old and add a `_v3` … and compare its
7	//! results … lazylock dispatch."* So this module is the **keep-old + add-v3 +
8	//! dispatch + compare** pattern:
9	//!
10	//!   - [`v3`] — the clean V3 path: reads the **full-resolution 3×256² SPO +
11	//!     3×256² AriGraph-basin true-centroid PAIRS** and scores them through the
12	//!     256×256 [`FisherZTable`] pairwise distribution over the Morton
13	//!     inverse-pyramid cascade.
14	//!   - [`legacy`] — the V1 path: the `3×8` **bare-index** read (only the first
15	//!     byte of each pair, as `CausalEdge64::{s_idx,p_idx,o_idx}` did). Kept for
16	//!     comparison; it structurally CANNOT see the pairwise partner (the `.1` of
17	//!     each pair = the AriGraph/full-resolution half) — which is exactly why
18	//!     running V1 over the V3 substrate is lossy.
19	//!   - [`read`] dispatches via [`BACKEND`] (LazyLock, default V3); [`compare`]
20	//!     runs both.
21	//!
22	//! The tenant carving is the established one (le-contract §3 L4 `palette256²`):
23	//! `6×(u8:u8)` = **3 SPO pairs (the fact) + 3 episodic-witness/AriGraph-basin
24	//! pairs (the support)**.
25	
26	pub mod legacy;
27	pub mod v3;
28	
29	use crate::fisher_z::FisherZTable;
30	use std::sync::LazyLock;
31	
32	/// The V3 L4 palette tenant: 12 bytes = `6×(u8:u8)` true-centroid pairs, carved
33	/// as 3 SPO + 3 episodic-witness/AriGraph-basin (full-resolution SPO + AriGraph).
34	#[derive(Clone, Copy, Debug, PartialEq, Eq)]
35	pub struct L4Tenant {
36	    /// 3×256² SPO true-centroid pairs — the SPO 2³ fact.
37	    pub spo: [(u8, u8); 3],
38	    /// 3×256² AriGraph SPO-G / episodic-witness basin pairs — the support.
39	    pub basins: [(u8, u8); 3],
40	}
41	
42	impl L4Tenant {
43	    /// Read the 12-byte L4 slice of a node's value tenant.
44	    pub fn from_bytes(b: &[u8; 12]) -> Self {
45	        L4Tenant {
46	            spo: [(b[0], b[1]), (b[2], b[3]), (b[4], b[5])],
47	            basins: [(b[6], b[7]), (b[8], b[9]), (b[10], b[11])],
48	        }
49	    }
50	    /// Serialize back to the 12-byte L4 slice.
51	    pub fn to_bytes(&self) -> [u8; 12] {
52	        [
53	            self.spo[0].0,
54	            self.spo[0].1,
55	            self.spo[1].0,
56	            self.spo[1].1,
57	            self.spo[2].0,
58	            self.spo[2].1,
59	            self.basins[0].0,
60	            self.basins[0].1,
61	            self.basins[1].0,
62	            self.basins[1].1,
63	            self.basins[2].0,
64	            self.basins[2].1,
65	        ]
66	    }
67	}
