69	/// A cognitive reading of the tenant: the SPO fact's internal coherence, the
70	/// basin support toward it, and the net (negative ⇒ inverted/ironic — the
71	/// qualia −8..+8 inversion the operator named).
72	#[derive(Clone, Copy, Debug, PartialEq)]
73	pub struct Reading {
74	    pub fact_coherence: f32,
75	    pub basin_support: f32,
76	    pub net: f32,
77	}
78	
79	/// Which substrate computes the reading.
80	#[derive(Clone, Copy, Debug, PartialEq, Eq)]
81	pub enum Backend {
82	    /// The clean V3 full-resolution 3×256² true-centroid path.
83	    V3,
84	    /// The legacy V1 3×8 bare-index path (lossy on the V3 substrate).
85	    Legacy,
86	}
87	
88	/// LazyLock dispatch: default V3; override with `BGZ_MORTON_BACKEND=legacy`
89	/// (or `p64`) for the legacy comparison path. Resolved once per process.
90	pub static BACKEND: LazyLock<Backend> =
91	    LazyLock::new(|| match std::env::var("BGZ_MORTON_BACKEND").as_deref() {
92	        Ok("legacy") | Ok("p64") | Ok("v1") => Backend::Legacy,
93	        _ => Backend::V3,
94	    });
95	
96	/// Read the tenant through the active backend (see [`BACKEND`]).
97	pub fn read(tenant: &L4Tenant, fz: &FisherZTable) -> Reading {
98	    match *BACKEND {
99	        Backend::V3 => v3::read(tenant, fz),
100	        Backend::Legacy => legacy::read(tenant, fz),
101	    }
102	}
103	
104	/// Compare thinking: run BOTH substrates on the same tenant. Returns
105	/// `(v3, legacy)`. When the pair partners (`.1`) carry signal the V1 bare-index
106	/// read cannot see, the two Readings DIVERGE — the measured cost of running V1
107	/// over V3.
108	pub fn compare(tenant: &L4Tenant, fz: &FisherZTable) -> (Reading, Reading) {
109	    (v3::read(tenant, fz), legacy::read(tenant, fz))
110	}
